#!/bin/bash -e

PKG="${1:?usage: $0 <pkg>}"
SLUG="$(sed -r 's:/:-:g' <<<"${PKG}")"

export BASE="$(readlink -f "$(dirname "$0")/../..")"

# Packages built against local copies of others (go.mod "replace ... => ../x")
# are tested when those change too.
PATHS=""
for dir in $(sed -nr 's:.*=>[[:space:]]*(\.\.?/[^[:space:]]*).*:\1:p' "$BASE/${PKG}/go.mod"); do
	dep="$(realpath -m --relative-to="$BASE" "$BASE/${PKG}/${dir}")"
	case "${dep}/" in "${PKG}/"*) continue ;; esac # Already covered by "${PKG}/**".
	PATHS+="
      - \"${dep}/**\""
done

cat <<EOF >"$BASE/.github/workflows/pkg-${SLUG}.yml"
# THIS FILE IS GENERATED BY "task workflows:all"! DO NOT EDIT!
name: pkg-${SLUG}

on:
  pull_request:
    branches: [master]
    paths:
      - "Taskfile.yaml"
      - "go.work*"
      - "${PKG}/**"${PATHS}
      - ".github/workflows/pkg-${SLUG}.yml"
    types: [opened, edited, reopened, synchronize, unlocked]
  push:
    branches: [master]
    paths:
      - "Taskfile.yaml"
      - "go.work*"
      - "${PKG}/**"${PATHS}
      - ".github/workflows/pkg-${SLUG}.yml"
  workflow_dispatch: {}

jobs:
  go-test:
    uses: lrstanley/.github/.github/workflows/lang-go-test-matrix.yml@master
    secrets: inherit
    with:
      num-minor: 1
      num-patch: 1
      working-directory: "${PKG}"
  go-lint:
    uses: lrstanley/.github/.github/workflows/lang-go-lint.yml@master
    secrets: inherit
    with:
      working-directory: "${PKG}"
EOF
